<datalist id="erp-material-options"><?php foreach($_['materials'] as $m): ?><option value="<?php p(trim(($m['article_no']??'').' · '.$m['name'],' ·')); ?>"><?php endforeach; ?></datalist>
<div id="app-content"><div class="erp-page"><h1>Zeiterfassung</h1><p class="erp-sub">Arbeitszeit und verbautes Material gemeinsam erfassen. Beides wird später zusammen in den Rapport und in die Abrechnung übernommen.</p>
