<h2>Projekt-Timer</h2>
<?php if($_['activeTimers']): ?><div class="erp-timers"><?php foreach($_['activeTimers'] as $t): ?><div class="erp-timer-card"><div><strong><?php p($t['user_id'].' · '.($t['project_no']??'').' '.($t['title']??'')); ?></strong><p><?php p($t['activity']); ?></p><small>Gestartet: <?php p(date('d.m.Y H:i',strtotime($t['started_at']))); ?> · Status: <?php p($t['status']==='paused'?'Pause':'läuft'); ?></small></div><div class="erp-timer-actions"><?php if($t['status']==='running'): ?><form method="post" action="<?php p($url->linkToRoute('reinhardterp.module.pauseTimer',['id'=>$t['id']])); ?>"><input type="hidden" name="requesttoken" value="<?php p($_['requesttoken']); ?>"><button class="button">Pause</button></form><?php else: ?><form method="post" action="<?php p($url->linkToRoute('reinhardterp.module.resumeTimer',['id'=>$t['id']])); ?>"><input type="hidden" name="requesttoken" value="<?php p($_['requesttoken']); ?>"><button class="button">Weiter</button></form><?php endif; ?><form method="post" action="<?php p($url->linkToRoute('reinhardterp.module.stopTimer',['id'=>$t['id']])); ?>"><input type="hidden" name="requesttoken" value="<?php p($_['requesttoken']); ?>"><button class="button primary">Feierabend / Stop</button></form></div></div><?php endforeach; ?></div><?php endif; ?>
